USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_Manager_GetPending @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,h.REQUESTED_ORG_UNIT_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=@EmployeeId AND u.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.DEV_USER du ON du.EMPLOYEE_ID=u.EMPLOYEE_ID JOIN dbo.DEV_USER_ROLE ur ON ur.DEV_USER_ID=du.DEV_USER_ID AND ur.IS_ACTIVE=1 JOIN dbo.ROLE_MASTER r ON r.ROLE_ID=ur.ROLE_ID AND r.ROLE_CODE='MANAGER' WHERE h.CURRENT_STATUS='SUBMITTED'; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Manager_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; DECLARE @org BIGINT,@status VARCHAR(40); SELECT @org=REQUESTED_ORG_UNIT_ID,@status=CURRENT_STATUS FROM dbo.REQUISITION_HEADER WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId; IF @status IS NULL THROW 51001,'Requisition not found.',1; IF @status<>'SUBMITTED' THROW 51003,'Manager approval requires SUBMITTED status.',1; IF NOT EXISTS(SELECT 1 FROM dbo.APP_USER_CACHE u JOIN dbo.DEV_USER du ON du.EMPLOYEE_ID=u.EMPLOYEE_ID AND du.IS_ACTIVE=1 JOIN dbo.DEV_USER_ROLE ur ON ur.DEV_USER_ID=du.DEV_USER_ID AND ur.IS_ACTIVE=1 JOIN dbo.ROLE_MASTER r ON r.ROLE_ID=ur.ROLE_ID WHERE u.EMPLOYEE_ID=@ActorEmployeeId AND u.ORG_UNIT_ID=@org AND r.ROLE_CODE='MANAGER') THROW 51002,'Actor is not an eligible manager.',1; UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1; UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='IN_WORKFLOW',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId; INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,CREATED_BY) VALUES(@RequisitionId,'PROCUREMENT_OFFICER_POOL',@ActorEmployeeId); INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID) VALUES(@RequisitionId,'MANAGER_APPROVE',@ActorEmployeeId,'MANAGER','MANAGER','PROCUREMENT_OFFICER',@Remarks,@BatchReferenceId); INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID) VALUES(@RequisitionId,'MANAGER','PROCUREMENT_OFFICER','MANAGER_APPROVE',@ActorEmployeeId,@Remarks,@BatchReferenceId); COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE ERROR_NUMBER() WHEN 51001 THEN '002' WHEN 51002 THEN '003' WHEN 51003 THEN '004' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Manager_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON; EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'MANAGER','SUBMITTED','MANAGER_RETURN','MANAGER_RETURNED','DRAFT',@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Manager_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN SET NOCOUNT ON; EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'MANAGER','SUBMITTED','MANAGER_REJECT','MANAGER_REJECTED','END',@Remarks,@BatchReferenceId; END;
GO
